// Refusal router + attempt log (deterministic pre-checks before the model)
function triageRequest(text) {
  const log = [];
  if (/ignore (previous )?instructions|system:|disregard/i.test(text)) {
    log.push("injection-pattern");
    return { route: "quarantine", reason: "instruction-like content in data", log };
  }
  if (/delete (my )?account|close account/i.test(text)) {
    log.push("out-of-scope");
    return { route: "refuse", reason: "account actions need the account team", log };
  }
  return { route: "handle", log };
}
// Deterministic patterns catch known attacks free; the model handles the rest
// under scope rules. Log every route — refusal spikes signal campaigns.

